def __rsub__(self, other):
    if isinstance(other, DatetimeLikeArrayMixin) or isinstance(other, np.timedelta64):
        msg = "Unsupported operand type(s) for -: '{}' and '{}'"
        raise TypeError(msg.format(type(self).__name__, type(other).__name__))
    elif isinstance(other, pd.Timedelta):
        result = self + (-other)
        return result
    else:
        raise ValueError(f"Unsupported operand type(s) for -: '{type(self).__name__}' and '{type(other).__name__}'")
